package main

import "fmt"

func sum(a, b int) int {
	x := a + b // stack: x dies when sum returns, reclaimed for free
	return x
}

func main() {
	// `go build -gcflags=-m` reports nothing escaping here — all on the stack.
	fmt.Println(sum(2, 3)) // Output: 5
}

package main

type T struct{ v int }

// The address of local stays inside the frame -> proven not to escape -> stack.
func noEscape() int {
	local := T{v: 7}
	p := &local // taking an address does NOT force the heap
	return p.v  // p never leaves the frame
}

// The address flows out via the return -> cannot prove containment -> heap.
func escapes() *T {
	local := T{v: 7}
	return &local // 'moved to heap: local'
}

var _ = noEscape
var _ = escapes

package main

import "fmt"

type User struct {
	Name string
	Age  int
}

// &u escapes; the compiler heap-allocates u so the pointer is always valid.
func newUser(name string, age int) *User {
	u := User{Name: name, Age: age}
	return &u // safe in Go — never a dangling pointer
}

func main() {
	u := newUser("Ada", 36)
	fmt.Printf("%s is %d\n", u.Name, u.Age) // Output: Ada is 36
}

package main

import "fmt"

func counter() func() int {
	n := 0 // ESCAPE: captured by a closure that outlives counter's frame
	return func() int {
		n++
		return n
	}
}

func main() {
	x := 42
	fmt.Println(x) // ESCAPE: x is boxed into interface{} for a non-inlined variadic call

	c := counter()
	fmt.Println(c(), c()) // Output: 42\n1 2
}

// Inspect the compiler's escape decisions and per-op allocations:
//
//   $ go build -gcflags='-m -l' ./...
//   ./main.go:13:2: moved to heap: u        // local promoted to the heap
//   ./main.go:11:13: name does not escape    // stays on the stack
//   ./main.go:18:14: u.Name escapes to heap  // via interface boxing
//
//   $ go test -bench . -benchmem
//   BenchmarkFormatKey-8   5000000   240 ns/op   48 B/op   3 allocs/op
//
// -l disables inlining so diagnostics line up with your source lines.

package main

import (
	"bytes"
	"sync"
)

// A pool amortizes an allocation that genuinely must escape, cutting GC pressure
// in a hot path by reusing buffers instead of allocating one per call.
var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

func render(parts []string) string {
	b := bufPool.Get().(*bytes.Buffer)
	b.Reset()
	defer bufPool.Put(b) // return for reuse -> fewer heap allocations, less GC work
	for _, p := range parts {
		b.WriteString(p)
	}
	return b.String()
}

var _ = render

