package main

import "fmt"

type Point struct{ X, Y int }

// Returning Point by value lets p stay on sumPoints's stack frame —
// no heap allocation. The small struct is copied cheaply to the caller.
func sumPoints(pts []Point) Point {
	p := Point{}
	for _, q := range pts {
		p.X += q.X
		p.Y += q.Y
	}
	return p // value copy, no escape
}

func main() {
	total := sumPoints([]Point{{1, 2}, {3, 4}})
	fmt.Println(total.X, total.Y) // 4 6
}

