package solution

type Stats struct {
	Sum int
	Max int
}

// Returning Stats by value lets the local s stay on Solve's stack frame.
// The small struct is copied cheaply to the caller — no heap allocation.
func Solve(vals []int) Stats {
	s := Stats{}
	if len(vals) == 0 {
		return s // zero value: Sum 0, Max 0
	}
	s.Max = vals[0]
	for _, v := range vals {
		s.Sum += v
		if v > s.Max {
			s.Max = v
		}
	}
	return s // value copy, does not escape
}

