package solution

import "testing"

func TestSolve(t *testing.T) {
	cases := []struct {
		in       []int
		wantSum  int
		wantMax  int
	}{
		{[]int{1, 2, 3}, 6, 3},
		{[]int{-5, -1, -9}, -15, -1},
		{[]int{}, 0, 0},
		{[]int{42}, 42, 42},
	}
	for _, c := range cases {
		got := Solve(c.in)
		if got.Sum != c.wantSum || got.Max != c.wantMax {
			t.Errorf("Solve(%v)={Sum:%d Max:%d} want {Sum:%d Max:%d}", c.in, got.Sum, got.Max, c.wantSum, c.wantMax)
		}
	}
}

