import (
	"strconv"
	"strings"
)

// No interface boxing: strconv.Itoa avoids ...interface{}, and the
// Builder grows a single backing array. One allocation for the result
// instead of several, and no per-arg heap boxing.
func formatKey(userID int, region string) string {
	var b strings.Builder
	b.Grow(len(region) + 16) // preallocate to avoid regrowth
	b.WriteString("u:")
	b.WriteString(strconv.Itoa(userID))
	b.WriteByte(':')
	b.WriteString(region)
	return b.String()
}

func Concat(parts []string) string {
	n := 0
	for _, p := range parts {
		n += len(p)
	}
	var b strings.Builder
	b.Grow(n) // single allocation sized to the final length
	for _, p := range parts {
		b.WriteString(p)
	}
	return b.String() // returned by value, not by pointer
}

package solution

import (
	"strconv"
	"strings"
)

// formatKey builds "u:<id>:<region>" with no interface boxing and a single
// result allocation. strconv.Itoa avoids the ...interface{} boxing that
// fmt.Sprintf incurs; Builder.Grow presizes so there's one backing array.
func formatKey(userID int, region string) string {
	var b strings.Builder
	b.Grow(len(region) + 16) // presize: avoids regrowth reallocations
	b.WriteString("u:")
	b.WriteString(strconv.Itoa(userID)) // no interface boxing
	b.WriteByte(':')
	b.WriteString(region)
	return b.String()
}

